 CLASSES.forEach((c,job)=>c.skills.forEach((sk,i)=>{if(!sk[6]||typeof sk[6]!=='object'||Array.isArray(sk[6]))sk[6]={};if(typeof sk[6].description!=='string')sk[6].description=CORE_SKILL_DEFAULT_DESCRIPTIONS[job]?.[i]||'';}));
