Object.assign(STATUS_TARGET_LABELS,{rankedAllies:'依能力排序的我方單位',rankedEnemies:'依能力排序的敵方單位'});
const ADVANCED_STATUS_TARGET_STATS=['attack','defense','maxHp','currentHp','missingHp','shield','level','crit'];
