      if(skillById.has(id))throw Error('核心技能 ID 重複：'+id);
      const usage=SHARED_USAGE_SCOPES.has(sk?.usageScope)?sk.usageScope:'character';
      skillById.set(id,{id,usage,effect:sk?.effect||'',name:sk?.name||id});
