        const kind=row?.kind,allowed=sk.usage==='shared'||((kind==='normal'||kind==='elite')&&(sk.usage==='elite'||kind==='normal'&&sk.usage==='monster'))||((kind==='boss'||kind==='final')&&sk.usage==='boss');
        if(!allowed)throw Error('怪物技能用途分類不相容：'+(row?.id||'未知怪物')+' → '+sk.name);
