  for(let job=0;job<CLASSES.length;job++)for(let i=0;i<CLASSES[job].skills.length;i++){CLASSES[job].skills[i][6]??={};CLASSES[job].skills[i][6].sharedId??=`job${job}-core${i}`;CLASSES[job].skills[i][6].usageScope??='character';}

